1	/**
2	 * Corpus filesystem abstraction (DD-009 sub-task S0+S1).
3	 *
4	 * `CorpusFS` is the single FS seam every later sub-task binds to:
5	 *   - S1 OPFS adapter implements it (always-on local cache)
6	 *   - S2 FSA folder mirror writes through it
7	 *   - S4 migration + session model reads/writes the folder layout through it
8	 *
9	 * Design notes (see docs/decisions/009-artifact-corpus-architecture.md and
10	 * docs/reviews/architecture-review.md):
11	 *  - Bytes + paths, not strings + keys. Sources are binary (PDFs), so the
12	 *    interface is `Uint8Array`-oriented; do not narrow it to strings.
13	 *  - Async everywhere. OPFS and FSA are both async, and DD-009 mandates the
14	 *    writer eventually run in a worker (S3). An async interface makes that a
15	 *    transport swap, not an interface change — so consumers MUST bind to this
16	 *    interface, never to a concrete adapter (arch-review finding 3).
17	 *  - "Not found" is `null` from `readFile`/`stat` and `[]` from `readdir`;
18	 *    everything else rejects with a `CorpusError`. Callers never see `undefined`.
19	 *  - GIT IS NOT PART OF THIS INTERFACE. S3's commit/log/push/pull belong on a
20	 *    separate `CorpusGit` interface that operates *over* a `CorpusFS`. Do not add
21	 *    git methods here — that would force the in-memory fake and every non-git
22	 *    consumer to stub operations they don't use (arch-review finding 2, ISP).
23	 */
24	
25	// ---------------------------------------------------------------------------
26	// Error model — one source of truth for the kind set (arch-review finding 1).
27	// `CorpusError` is the thrown form; `CorpusWorkerError` is its postMessage-
28	// serializable twin. They differ only in transport, never in the kind set.
29	// ---------------------------------------------------------------------------
30	
31	/** Which substrate raised a space/quota failure. Substrate-neutral so S2 (FSA)
32	 *  and future caches reuse the same `quota-exceeded` kind rather than minting
33	 *  adapter-specific kinds the exhaustive switches would all have to learn. */
34	export type CorpusSubstrate = "opfs" | "fsa" | "remote";
35	
36	/**
37	 * The complete set of corpus failure kinds. Every exhaustive `switch` over a
38	 * corpus error binds to this union; adding a kind here forces every consumer to
39	 * handle it at compile time (the failure-driven-UI mandate, DD-009 §Failure-driven).
40	 */
41	export type CorpusErrorKind =
42	  | { kind: "not-found"; path: string }
43	  | { kind: "quota-exceeded"; substrate: CorpusSubstrate; needed?: number; available?: number }
44	  | { kind: "unavailable"; reason: string } // e.g. SSR / no navigator.storage
45	  | { kind: "io"; path: string; reason: string }
46	  | { kind: "fsa-permission-revoked" }
47	  | { kind: "remote-auth-expired" }
48	  | { kind: "browser-storage-cleared" }
49	  | { kind: "git-conflict"; path: string };
50	
51	/** Thrown form of a corpus failure. `detail` carries the discriminated kind. */
52	export class CorpusError extends Error {
53	  readonly detail: CorpusErrorKind;
54	  constructor(detail: CorpusErrorKind, message?: string) {
55	    super(message ?? describeCorpusError(detail));
56	    this.name = "CorpusError";
57	    this.detail = detail;
58	  }
59	}
60	
61	/** Serializable twin for crossing a worker boundary (S3). Reconstruct with
62	 *  `new CorpusError(payload.detail, payload.message)` on the main thread. */
63	export type CorpusWorkerError = {
64	  __corpusError: true;
65	  detail: CorpusErrorKind;
66	  message: string;
67	};
68	
69	export function toWorkerError(err: CorpusError): CorpusWorkerError {
70	  return { __corpusError: true, detail: err.detail, message: err.message };
71	}
72	
73	export function isCorpusWorkerError(v: unknown): v is CorpusWorkerError {
74	  return typeof v === "object" && v !== null && (v as { __corpusError?: unknown }).__corpusError === true;
75	}
76	
77	/** Human-readable default message for a kind (used when no override is given). */
78	export function describeCorpusError(d: CorpusErrorKind): string {
79	  switch (d.kind) {
80	    case "not-found": return `corpus path not found: ${d.path}`;
81	    case "quota-exceeded": return `corpus storage quota exceeded (${d.substrate})`;
82	    case "unavailable": return `corpus storage unavailable: ${d.reason}`;
83	    case "io": return `corpus i/o error at ${d.path}: ${d.reason}`;
84	    case "fsa-permission-revoked": return "corpus folder permission was revoked";
85	    case "remote-auth-expired": return "corpus remote authentication expired";
86	    case "browser-storage-cleared": return "corpus browser storage was cleared";
87	    case "git-conflict": return `corpus git conflict at ${d.path}`;
88	    default: return assertNever(d);
89	  }
90	}
91	
92	/** Compile-time exhaustiveness guard. Reaching this at runtime means a kind was
93	 *  added to `CorpusErrorKind` without updating a switch — TS flags it first. */
94	export function assertNever(x: never): never {
95	  throw new Error(`unhandled corpus error kind: ${JSON.stringify(x)}`);
96	}
97	
98	// ---------------------------------------------------------------------------
99	// The filesystem interface.
100	// ---------------------------------------------------------------------------
101	
102	export interface CorpusStat {
103	  size: number;
104	}
105	
106	/**
107	 * Async, bytes-and-paths filesystem seam. Paths are POSIX-style, relative to the
108	 * corpus root, using "/" separators and no leading slash (e.g.
109	 * "workspaces/my-slug/artifacts/semiformal/v0001.md"). Implementations create
110	 * intermediate directories on write.
111	 */
112	export interface CorpusFS {
113	  /** Returns file bytes, or `null` if the path does not exist. Rejects with a
114	   *  `CorpusError` for any other failure. */
115	  readFile(path: string): Promise<Uint8Array | null>;
116	  /** Writes bytes, creating intermediate directories as needed. */
117	  writeFile(path: string, bytes: Uint8Array): Promise<void>;
118	  /** Lists immediate child names of a directory; `[]` if the directory is
119	   *  missing or empty. Names only, not full paths. */
120	  readdir(path: string): Promise<string[]>;
121	  /** Removes a file. Idempotent: resolves (no-op) if the path does not exist. */
122	  rm(path: string): Promise<void>;
123	  /** Returns `{ size }` for an existing file, or `null` if it does not exist. */
124	  stat(path: string): Promise<CorpusStat | null>;
125	}
