1	/**
2	 * Corpus folder-layout path builders (DD-009 sub-task S0).
3	 *
4	 * The on-disk shape (DD-009 §Folder layout):
5	 *
6	 *   <corpus-root>/
7	 *   ├── settings.json
8	 *   └── workspaces/<slug>/
9	 *       ├── workspace.json
10	 *       ├── sources/<source-id>.<ext>
11	 *       ├── artifacts/<type>/v####.md   (+ meta.json per type)
12	 *       ├── custom-types/<custom-type-id>.json
13	 *       └── decomposition/...
14	 *
15	 * All builders return POSIX-style paths relative to the corpus root (no leading
16	 * slash), suitable for passing straight to a `CorpusFS`. The only source of
17	 * corpus paths is this module — callers must never hand-concatenate, so the
18	 * traversal guard in `workspaceSlug` is the single choke point that keeps
19	 * untrusted workspace titles inside `workspaces/`.
20	 */
21	
22	/** Width of the zero-padded version number in artifact filenames (v0001.md). */
23	const VERSION_PAD = 4;
24	
25	/** Characters allowed in a sanitized slug or id segment. Everything else is
26	 *  collapsed to a hyphen so a value can never contain "/", "\\", "." runs, or
27	 *  control characters that would let it escape its directory. */
28	const SAFE_SEGMENT = /[^a-zA-Z0-9_-]+/g;
29	
30	/**
31	 * Sanitize a workspace title into a filesystem-safe slug that cannot escape
32	 * `workspaces/`. Strips path separators, dot-segments, and unicode; collapses
33	 * runs of unsafe characters to a single hyphen; trims leading/trailing hyphens.
34	 * Throws if nothing safe remains (an all-unsafe title must not silently become "").
35	 */
36	export function workspaceSlug(title: string): string {
37	  const slug = title
38	    .normalize("NFKD")
39	    .replace(SAFE_SEGMENT, "-")
40	    .replace(/-{2,}/g, "-")
41	    .replace(/^-+|-+$/g, "")
42	    .toLowerCase();
43	  if (!slug) {
44	    throw new Error(`workspace title produced an empty slug: ${JSON.stringify(title)}`);
45	  }
46	  return slug;
47	}
48	
49	/** Sanitize an arbitrary id (source id, custom-type id, artifact type) for use
50	 *  as a single path segment. Same guarantees as `workspaceSlug` but preserves
51	 *  case (ids are typically already safe, e.g. "custom-abc123"). */
52	export function safeSegment(id: string): string {
53	  const seg = id.normalize("NFKD").replace(SAFE_SEGMENT, "-").replace(/-{2,}/g, "-").replace(/^-+|-+$/g, "");
54	  if (!seg) {
55	    throw new Error(`id produced an empty path segment: ${JSON.stringify(id)}`);
56	  }
57	  return seg;
58	}
59	
60	/** Sanitize a file extension to alphanumerics; defaults to "bin" if empty. */
61	function safeExt(ext: string): string {
62	  const e = ext.replace(/^\.+/, "").replace(/[^a-zA-Z0-9]+/g, "").toLowerCase();
63	  return e || "bin";
64	}
65	
66	// --- Path builders (all relative to corpus root) ---------------------------
67	
68	export const SETTINGS_PATH = "settings.json";
69	
70	export function workspaceDir(slug: string): string {
71	  return `workspaces/${workspaceSlug(slug)}`;
72	}
73	
74	export function workspaceManifestPath(slug: string): string {
75	  return `${workspaceDir(slug)}/workspace.json`;
76	}
77	
78	export function sourcePath(slug: string, sourceId: string, ext: string): string {
79	  return `${workspaceDir(slug)}/sources/${safeSegment(sourceId)}.${safeExt(ext)}`;
80	}
81	
82	export function artifactDir(slug: string, artifactType: string): string {
83	  return `${workspaceDir(slug)}/artifacts/${safeSegment(artifactType)}`;
84	}
85	
86	/** Zero-padded version file, e.g. artifactVersionPath(s,"semiformal",1) ->
87	 *  "workspaces/<s>/artifacts/semiformal/v0001.md". `version` is 1-based. */
88	export function artifactVersionPath(slug: string, artifactType: string, version: number): string {
89	  if (!Number.isInteger(version) || version < 1) {
90	    throw new Error(`artifact version must be a positive integer, got ${version}`);
91	  }
92	  const v = String(version).padStart(VERSION_PAD, "0");
93	  return `${artifactDir(slug, artifactType)}/v${v}.md`;
94	}
95	
96	export function artifactMetaPath(slug: string, artifactType: string): string {
97	  return `${artifactDir(slug, artifactType)}/meta.json`;
98	}
99	
100	export function customTypePath(slug: string, customTypeId: string): string {
101	  return `${workspaceDir(slug)}/custom-types/${safeSegment(customTypeId)}.json`;
102	}
103	
104	export function decompositionDir(slug: string): string {
105	  return `${workspaceDir(slug)}/decomposition`;
106	}
107	
108	export function decompositionGraphLayoutPath(slug: string): string {
109	  return `${decompositionDir(slug)}/graph-layout.json`;
110	}
111

1	/**
2	 * `workspace.json` manifest schema + codec (DD-009 sub-task S0).
3	 *
4	 * The manifest is the index for one workspace folder: it lists the sources, the
5	 * current-version pointer per artifact type, and the custom-type ids present.
6	 * The per-version artifact bytes live in files (artifacts/<type>/v####.md), not
7	 * here — the manifest only points at the current version so a consumer can open
8	 * a workspace without scanning every file.
9	 *
10	 * Codec contract (arch-review / test-strategy G11): parsing is FAIL-LOUD. A
11	 * malformed or absent manifest must surface as a typed `CorpusError` of kind
12	 * "io" or "browser-storage-cleared", never a silent default-empty manifest that
13	 * would masquerade as "this workspace has no work in it" and mask data loss.
14	 */
15	
16	import { CorpusError } from "./types";
17	
18	export const MANIFEST_VERSION = 1;
19	
20	/** Pointer to the current version of one artifact type. `currentVersion` is the
21	 *  1-based version number whose file is artifacts/<type>/v####.md. */
22	export interface ArtifactPointer {
23	  type: string;
24	  currentVersion: number;
25	}
26	
27	export interface SourceRef {
28	  id: string;
29	  label: string;
30	  /** File extension (no dot) of the stored source bytes under sources/. */
31	  ext: string;
32	}
33	
34	export interface WorkspaceManifest {
35	  manifestVersion: number;
36	  title: string;
37	  createdAt: string;
38	  updatedAt: string;
39	  sources: SourceRef[];
40	  artifacts: ArtifactPointer[];
41	  customTypeIds: string[];
42	}
43	
44	export function createManifest(title: string, now = new Date().toISOString()): WorkspaceManifest {
45	  return {
46	    manifestVersion: MANIFEST_VERSION,
47	    title,
48	    createdAt: now,
49	    updatedAt: now,
50	    sources: [],
51	    artifacts: [],
52	    customTypeIds: [],
53	  };
54	}
55	
56	export function serializeManifest(m: WorkspaceManifest): Uint8Array {
57	  return new TextEncoder().encode(JSON.stringify(m, null, 2));
58	}
59	
60	function isObject(v: unknown): v is Record<string, unknown> {
61	  return typeof v === "object" && v !== null && !Array.isArray(v);
62	}
63	
64	function fail(reason: string): never {
65	  // Manifest parse failure is an i/o-class corruption of the workspace index.
66	  throw new CorpusError({ kind: "io", path: "workspace.json", reason }, `invalid workspace.json: ${reason}`);
67	}
68	
69	/**
70	 * Parse + validate manifest bytes. Throws a `CorpusError` on any malformation —
71	 * a `null` input (file absent) is the caller's responsibility to detect via
72	 * `CorpusFS.readFile` returning `null`; passing `null` here is itself an error.
73	 */
74	export function parseManifest(bytes: Uint8Array | null): WorkspaceManifest {
75	  if (bytes === null) fail("manifest file is absent");
76	  let raw: unknown;
77	  try {
78	    raw = JSON.parse(new TextDecoder().decode(bytes));
79	  } catch (e) {
80	    fail(`not valid JSON (${(e as Error).message})`);
81	  }
82	  if (!isObject(raw)) fail("top-level value is not an object");
83	  if (typeof raw.title !== "string") fail("missing required field: title");
84	  if (typeof raw.manifestVersion !== "number") fail("missing required field: manifestVersion");
85	
86	  const sources: SourceRef[] = Array.isArray(raw.sources)
87	    ? raw.sources.filter(isObject).map((s) => {
88	        if (typeof s.id !== "string" || typeof s.ext !== "string") fail("source entry missing id/ext");
89	        return { id: s.id, label: typeof s.label === "string" ? s.label : s.id, ext: s.ext };
90	      })
91	    : fail("missing or invalid field: sources");
92	
93	  const artifacts: ArtifactPointer[] = Array.isArray(raw.artifacts)
94	    ? raw.artifacts.filter(isObject).map((a) => {
95	        if (typeof a.type !== "string" || typeof a.currentVersion !== "number") {
96	          fail("artifact pointer missing type/currentVersion");
97	        }
98	        return { type: a.type as string, currentVersion: a.currentVersion as number };
99	      })
100	    : fail("missing or invalid field: artifacts");
101	
102	  const customTypeIds: string[] = Array.isArray(raw.customTypeIds)
103	    ? raw.customTypeIds.filter((x): x is string => typeof x === "string")
104	    : fail("missing or invalid field: customTypeIds");
105	
106	  return {
107	    manifestVersion: raw.manifestVersion,
108	    title: raw.title,
109	    createdAt: typeof raw.createdAt === "string" ? raw.createdAt : new Date().toISOString(),
110	    updatedAt: typeof raw.updatedAt === "string" ? raw.updatedAt : new Date().toISOString(),
111	    sources,
112	    artifacts,
113	    customTypeIds,
114	  };
115	}
