183	
184	  // Artifact versioning
185	  setArtifactGenerated: (key: ArtifactKey, content: string) => void;
186	  setArtifactsBatchGenerated: (entries: Array<{ key: ArtifactKey; content: string }>) => void;
187	  setArtifactEdited: (key: ArtifactKey, content: string, source: "ai-edit" | "manual-edit", instruction?: string) => void;
188	  undoArtifact: (key: ArtifactKey) => void;
189	  redoArtifact: (key: ArtifactKey) => void;
190	  getArtifactContent: (key: ArtifactKey) => string | null;
191	  canUndo: (key: ArtifactKey) => boolean;
192	  canRedo: (key: ArtifactKey) => boolean;
193	
194	  // Decomposition
195	  setDecomposition: (d: PersistedDecomposition) => void;
196	
197	  // Custom artifact types
198	  setCustomArtifactTypes: (v: CustomArtifactTypeDefinition[]) => void;
199	  addCustomArtifactType: (def: CustomArtifactTypeDefinition) => void;
200	  updateCustomArtifactType: (id: string, updates: Partial<CustomArtifactTypeDefinition>) => void;
201	  removeCustomArtifactType: (id: string) => void;
202	  setCustomArtifactContent: (id: CustomArtifactTypeId, content: string | null) => void;
203	
204	  // Snapshot/restore (for workspace sessions)
205	  getSnapshot: () => WorkspaceState;
206	  resetToSnapshot: (data: WorkspaceState) => void;
207	  clearWorkspace: () => void;
208	}
209	
210	// ---------------------------------------------------------------------------
211	// Default state
212	// ---------------------------------------------------------------------------
213	
214	const DEFAULT_STATE: WorkspaceState = {
215	  sourceText: "",
216	  extractedFiles: [],
217	  contextText: "",
218	  semiformalText: "",
219	  leanCode: "",
220	  semiformalDirty: false,
221	  verificationStatus: "none",
222	  verificationErrors: "",
223	  artifacts: {},
224	  decomposition: {
225	    nodes: [],
226	    selectedNodeId: null,
227	    paperText: "",
228	    sources: [],
229	  },
230	  customArtifactTypes: [],
231	  customArtifactData: {},
232	};
233	
234	// ---------------------------------------------------------------------------
235	// Migration from workspace-v2 (old useWorkspacePersistence format)
236	// ---------------------------------------------------------------------------
237	
238	/** Map from PersistedWorkspace flat fields to versioned ArtifactKey */
239	export const PERSISTED_ARTIFACT_FIELDS: Record<string, ArtifactKey> = {
240	  causalGraph: "causal-graph",
241	  statisticalModel: "statistical-model",
242	  propertyTests: "property-tests",
243	  dialecticalMap: "dialectical-map",
244	  counterexamples: "counterexamples",
245	};
246	
247	/**
248	 * Migrate data from workspace-v2 localStorage format into the Zustand store.
249	 * Called once on app load if the Zustand key is absent but workspace-v2 exists.
250	 */
251	export function migrateFromV2(): boolean {
252	  const old = loadWorkspace();
253	  if (!old) return false;
254	
255	  // Build versioned artifact records from flat PersistedWorkspace strings
256	  const artifacts: Partial<Record<ArtifactKey, ArtifactRecord>> = {};
257	  for (const [field, key] of Object.entries(PERSISTED_ARTIFACT_FIELDS)) {
258	    const content = old[field as keyof PersistedWorkspace];
259	    if (typeof content === "string" && content) {
260	      artifacts[key] = {
261	        type: key,
262	        currentVersionIndex: 0,
263	        versions: [makeVersion(content, "generated")],
264	      };
265	    }
266	  }
267	
268	  // Single setState call — matches the batching pattern in resetWorkspaceToSnapshot
269	  useWorkspaceStore.setState({
270	    sourceText: old.sourceText,
271	    extractedFiles: old.extractedFiles,
272	    contextText: old.contextText,
273	    semiformalText: old.semiformalText,
274	    leanCode: old.leanCode,
275	    semiformalDirty: old.semiformalDirty,
276	    verificationStatus: old.verificationStatus,
277	    verificationErrors: old.verificationErrors,
278	    decomposition: old.decomposition,
279	    artifacts,
280	    customArtifactTypes: old.customArtifactTypes ?? [],
281	    customArtifactData: old.customArtifactData ?? {},
282	  });
283	
284	  return true;
285	}
286	
287	// ---------------------------------------------------------------------------
288	// Partialize memoization — avoid re-mapping decomposition nodes on every set()
289	// when only unrelated fields (e.g., sourceText) changed.
290	// ---------------------------------------------------------------------------
291	
292	let _lastDecompRef: PersistedDecomposition | null = null;
293	let _lastDecompSanitized: PersistedDecomposition | null = null;
294	
295	function sanitizeDecomposition(decomposition: PersistedDecomposition): PersistedDecomposition {
296	  if (decomposition === _lastDecompRef && _lastDecompSanitized) {
297	    return _lastDecompSanitized;
298	  }
299	  const result = {
300	    ...decomposition,
301	    nodes: decomposition.nodes.map((n: PropositionNode) => ({
302	      ...n,
303	      verificationStatus: sanitizeNodeStatus(n.verificationStatus),
304	    })),
305	  };
306	  _lastDecompRef = decomposition;
307	  _lastDecompSanitized = result;
308	  return result;
309	}
310	
311	// ---------------------------------------------------------------------------
312	// Store
313	// ---------------------------------------------------------------------------
314	
315	export const useWorkspaceStore = create<WorkspaceState & WorkspaceActions>()(
316	  persist(
317	    (set, get) => ({
318	      ...DEFAULT_STATE,
319	
320	      // --- Simple setters ---
321	      setSourceText: (v) => set({ sourceText: v }),
322	      setExtractedFiles: (v) => set({ extractedFiles: v }),
323	      setContextText: (v) => set({ contextText: v }),
324	      setSemiformalText: (v) =>
325	        set((s) => ({
326	          semiformalText: typeof v === "function" ? v(s.semiformalText) : v,
327	        })),
328	      setLeanCode: (v) =>
329	        set((s) => ({
330	          leanCode: typeof v === "function" ? v(s.leanCode) : v,
331	        })),
332	      setSemiformalDirty: (v) =>
333	        set((s) => ({
334	          semiformalDirty: typeof v === "function" ? v(s.semiformalDirty) : v,
335	        })),
336	      setVerificationStatus: (v) => set({ verificationStatus: v }),
337	      setVerificationErrors: (v) => set({ verificationErrors: v }),
338	
339	      // --- Artifact versioning ---
340	      setArtifactGenerated: (key, content) =>
341	        set((s) => {
342	          const existing = s.artifacts[key];
343	          const version = makeVersion(content, "generated");
344	          const versions = existing
345	            ? [...existing.versions.slice(-MAX_VERSIONS + 1), version]
346	            : [version];
347	          return {
348	            artifacts: {
349	              ...s.artifacts,
350	              [key]: {
351	                type: key,
352	                currentVersionIndex: versions.length - 1,
353	                versions,
354	              },
355	            },
356	          };
357	        }),
358	
359	      setArtifactsBatchGenerated: (entries) =>
360	        set((s) => {
361	          const updated = { ...s.artifacts };
362	          for (const { key, content } of entries) {
363	            const existing = updated[key];
364	            const version = makeVersion(content, "generated");
365	            const versions = existing
366	              ? [...existing.versions.slice(-MAX_VERSIONS + 1), version]
367	              : [version];
368	            updated[key] = { type: key, currentVersionIndex: versions.length - 1, versions };
369	          }
370	          return { artifacts: updated };
371	        }),
372	
373	      setArtifactEdited: (key, content, source, instruction) =>
374	        set((s) => {
375	          const existing = s.artifacts[key];
376	          if (!existing) {
377	            const version = makeVersion(content, source, instruction);
378	            return {
379	              artifacts: {
380	                ...s.artifacts,
381	                [key]: { type: key, currentVersionIndex: 0, versions: [version] },
382	              },
383	            };
384	          }
385	          // Truncate redo history when making a new edit
386	          const version = makeVersion(content, source, instruction);
387	          const truncated = existing.versions.slice(0, existing.currentVersionIndex + 1);
388	          const versions = [...truncated.slice(-MAX_VERSIONS + 1), version];
389	          return {
390	            artifacts: {
391	              ...s.artifacts,
392	              [key]: {
393	                type: key,
394	                currentVersionIndex: versions.length - 1,
395	                versions,
396	              },
397	            },
398	          };
399	        }),
400	
401	      undoArtifact: (key) =>
402	        set((s) => {
403	          const rec = s.artifacts[key];
404	          if (!rec || rec.currentVersionIndex <= 0) return s;
405	          return {
406	            artifacts: {
407	              ...s.artifacts,
408	              [key]: { ...rec, currentVersionIndex: rec.currentVersionIndex - 1 },
409	            },
410	          };
411	        }),
412	
413	      redoArtifact: (key) =>
414	        set((s) => {
415	          const rec = s.artifacts[key];
416	          if (!rec || rec.currentVersionIndex >= rec.versions.length - 1) return s;
417	          return {
418	            artifacts: {
419	              ...s.artifacts,
420	              [key]: { ...rec, currentVersionIndex: rec.currentVersionIndex + 1 },
421	            },
422	          };
423	        }),
424	
425	      getArtifactContent: (key) => resolveArtifactContent(get().artifacts[key]),
426	
427	      canUndo: (key) => {
428	        const rec = get().artifacts[key];
429	        return !!rec && rec.currentVersionIndex > 0;
430	      },
431	
432	      canRedo: (key) => {
433	        const rec = get().artifacts[key];
434	        return !!rec && rec.currentVersionIndex < rec.versions.length - 1;
435	      },
436	
437	      // --- Decomposition ---
438	      setDecomposition: (d) => set({ decomposition: d }),
439	
440	      // --- Custom artifact types ---
441	      setCustomArtifactTypes: (v) => set({ customArtifactTypes: v }),
442	      addCustomArtifactType: (def) =>
443	        set((s) => ({ customArtifactTypes: [...s.customArtifactTypes, def] })),
444	      updateCustomArtifactType: (id, updates) =>
445	        set((s) => {
446	          const old = s.customArtifactTypes.find((ct) => ct.id === id);
447	          // Clear generated output if the system prompt changed — stored
448	          // output is now stale w.r.t. the new prompt.
449	          const promptChanged = updates.systemPrompt != null && old && updates.systemPrompt !== old.systemPrompt;
450	          return {
451	            customArtifactTypes: s.customArtifactTypes.map((ct) =>
452	              ct.id === id ? { ...ct, ...updates, updatedAt: new Date().toISOString() } : ct,
453	            ),
454	            ...(promptChanged ? { customArtifactData: { ...s.customArtifactData, [id]: null } } : {}),
455	          };
456	        }),
457	      removeCustomArtifactType: (id) =>
458	        set((s) => ({
459	          customArtifactTypes: s.customArtifactTypes.filter((ct) => ct.id !== id),
460	          customArtifactData: Object.fromEntries(
461	            Object.entries(s.customArtifactData).filter(([k]) => k !== id),
462	          ),
463	        })),
464	      setCustomArtifactContent: (id, content) =>
465	        set((s) =>
466	          s.customArtifactData[id] === content
467	            ? s
468	            : { customArtifactData: { ...s.customArtifactData, [id]: content } },
469	        ),
470	
471	      // --- Snapshot/restore ---
472	      getSnapshot: () => {
473	        const s = get();
474	        return {
475	          sourceText: s.sourceText,
476	          extractedFiles: s.extractedFiles.map(({ name, text }) => ({ name, text })),
477	          contextText: s.contextText,
478	          semiformalText: s.semiformalText,
479	          leanCode: s.leanCode,
480	          semiformalDirty: s.semiformalDirty,
481	          verificationStatus: sanitizeVerificationStatus(s.verificationStatus),
482	          verificationErrors: s.verificationErrors,
483	          artifacts: structuredClone(s.artifacts),
484	          decomposition: structuredClone(s.decomposition),
485	          customArtifactTypes: structuredClone(s.customArtifactTypes),
486	          customArtifactData: { ...s.customArtifactData },
487	        };
488	      },
489	
490	      resetToSnapshot: (data) => set({ ...data }),
491	
492	      clearWorkspace: () => set({ ...DEFAULT_STATE }),
493	    }),
494	    {
495	      name: "workspace-zustand-v1",
496	      // Storage seam is selected here (DD-009 S1): debounced localStorage by
497	      // default, or a CorpusFS-backed adapter when the dev flag is on. The seam
498	      // is typed as CorpusFS so the S3 worker-proxy is a drop-in.
499	      storage: createJSONStorage(resolveWorkspaceStorage),
500	      // SSR safe: render defaults first, hydrate in useEffect via rehydrate()
501	      skipHydration: true,
502	      // Validate deserialized localStorage data before merging into the store.
503	      // Reuses coerceDecomposition from workspacePersistence for node-level field validation.
504	      merge: (persisted, current) => ({
505	        ...current,
506	        ...(isObject(persisted) ? coercePersistedState(persisted as Record<string, unknown>) : {}),
507	      }),
508	      // Only persist data fields, not action functions
509	      // File references on extractedFiles are non-serializable and dropped by JSON.stringify,
510	      // so no need to .map() here — save the allocation on every set() call.
511	      partialize: (state) => ({
512	        sourceText: state.sourceText,
513	        extractedFiles: state.extractedFiles,
514	        contextText: state.contextText,
515	        semiformalText: state.semiformalText,
516	        leanCode: state.leanCode,
517	        semiformalDirty: state.semiformalDirty,
518	        // Strip transient "verifying" back to "none" so a browser close during
519	        // verification doesn't leave the app stuck in a loading state on reload.
520	        verificationStatus: sanitizeVerificationStatus(state.verificationStatus),
521	        verificationErrors: state.verificationErrors,
522	        artifacts: state.artifacts,
523	        decomposition: sanitizeDecomposition(state.decomposition),
524	        customArtifactTypes: state.customArtifactTypes,
525	        customArtifactData: state.customArtifactData,
526	      }),
527	      // On rehydrate, check if we need to migrate from workspace-v2
528	      onRehydrateStorage: () => {
529	        return (_state, error) => {
530	          if (error) return;
531	          // If Zustand store was empty (no persisted data) but workspace-v2 exists,
532	          // migrate the old data. We check by looking for the old key.
533	          if (typeof window !== "undefined" && localStorage.getItem(WORKSPACE_KEY)) {
534	            const zustandRaw = localStorage.getItem("workspace-zustand-v1");
535	            let hasZustandData = false;
536	            try { hasZustandData = !!(zustandRaw && JSON.parse(zustandRaw)?.state?.sourceText); }
537	            catch { /* corrupted localStorage — proceed with migration */ }
538	            if (!hasZustandData) {
539	              migrateFromV2();
540	            }
541	          }
542	        };
543	      },
544	    },
545	  ),
546	);
