1	/**
2	 * Map-backed in-memory `CorpusFS` for tests (DD-009 sub-task S1).
3	 *
4	 * Lets corpus logic be verified in CI even though jsdom has no OPFS. The OPFS
5	 * adapter and this fake are both asserted against the same shared contract suite
6	 * (corpusFsContract.ts), so substitutability (LSP) is verified, not assumed.
7	 *
8	 * Directories are implicit: a file at "a/b/c.txt" makes "a" and "a/b" listable.
9	 */
10	
11	import type { CorpusFS, CorpusStat } from "../types";
12	
13	function normalize(path: string): string {
14	  return path.replace(/^\/+|\/+$/g, "");
15	}
16	
17	export function createInMemoryCorpusFs(): CorpusFS {
18	  const files = new Map<string, Uint8Array>();
19	
20	  return {
21	    async readFile(path) {
22	      return files.get(normalize(path)) ?? null;
23	    },
24	
25	    async writeFile(path, bytes) {
26	      // Copy so later mutation of the caller's array can't alter stored bytes.
27	      files.set(normalize(path), bytes.slice());
28	    },
29	
30	    async readdir(path) {
31	      const dir = normalize(path);
32	      const prefix = dir === "" ? "" : `${dir}/`;
33	      const children = new Set<string>();
34	      for (const key of files.keys()) {
35	        if (prefix !== "" && !key.startsWith(prefix)) continue;
36	        const rest = key.slice(prefix.length);
37	        if (rest === "") continue;
38	        const next = rest.split("/")[0];
39	        if (next) children.add(next);
40	      }
41	      return [...children].sort();
42	    },
43	
44	    async rm(path) {
45	      files.delete(normalize(path)); // idempotent: Map.delete on a missing key is a no-op
46	    },
47	
48	    async stat(path): Promise<CorpusStat | null> {
49	      const bytes = files.get(normalize(path));
50	      return bytes ? { size: bytes.byteLength } : null;
51	    },
52	  };
53	}
54

1	/**
2	 * Shared `CorpusFS` contract suite (DD-009 sub-task S1).
3	 *
4	 * Any `CorpusFS` implementation must pass this. Run against the in-memory fake
5	 * in CI (corpusFs.contract.test.ts) and against the real OPFS adapter via
6	 * out-of-CI Playwright (jsdom has no OPFS). Keeping the cases in one place means
7	 * the fake and the adapter are held to identical behavior (substitutability).
8	 */
9	
10	import { describe, it, expect, beforeEach } from "vitest";
11	import type { CorpusFS } from "../types";
12	
13	/** @param makeFs returns a fresh, empty CorpusFS for each test. */
14	export function defineCorpusFsContract(label: string, makeFs: () => CorpusFS | Promise<CorpusFS>): void {
15	  describe(`CorpusFS contract: ${label}`, () => {
16	    let fs: CorpusFS;
17	    beforeEach(async () => {
18	      fs = await makeFs();
19	    });
20	
21	    it("returns null for a missing file (readFile) and missing stat", async () => {
22	      expect(await fs.readFile("absent.txt")).toBeNull();
23	      expect(await fs.stat("absent.txt")).toBeNull();
24	    });
25	
26	    it("returns [] for a missing/empty directory (readdir)", async () => {
27	      expect(await fs.readdir("nope")).toEqual([]);
28	    });
29	
30	    it("round-trips all 256 byte values exactly", async () => {
31	      const bytes = new Uint8Array(256);
32	      for (let i = 0; i < 256; i++) bytes[i] = i;
33	      await fs.writeFile("bin/all-bytes.dat", bytes);
34	      const out = await fs.readFile("bin/all-bytes.dat");
35	      expect(out).not.toBeNull();
36	      // Compare as arrays for a readable diff on failure.
37	      expect(Array.from(out!)).toEqual(Array.from(bytes));
38	      expect((await fs.stat("bin/all-bytes.dat"))?.size).toBe(256);
39	    });
40	
41	    it("creates intermediate directories and lists children at each level", async () => {
42	      await fs.writeFile("workspaces/s/artifacts/semiformal/v0001.md", new TextEncoder().encode("x"));
43	      expect(await fs.readdir("workspaces")).toEqual(["s"]);
44	      expect(await fs.readdir("workspaces/s")).toEqual(["artifacts"]);
45	      expect(await fs.readdir("workspaces/s/artifacts")).toEqual(["semiformal"]);
46	      expect(await fs.readdir("workspaces/s/artifacts/semiformal")).toEqual(["v0001.md"]);
47	    });
48	
49	    it("rm removes a file and is idempotent on a missing path", async () => {
50	      await fs.writeFile("a.txt", new TextEncoder().encode("hi"));
51	      await fs.rm("a.txt");
52	      expect(await fs.readFile("a.txt")).toBeNull();
53	      // Second rm (and rm of never-existed) must not throw.
54	      await expect(fs.rm("a.txt")).resolves.toBeUndefined();
55	      await expect(fs.rm("never-existed.txt")).resolves.toBeUndefined();
56	    });
57	
58	    it("handles the S4 access pattern: 30 small files in one artifact dir (arch-review finding 4)", async () => {
59	      const dir = "workspaces/s/artifacts/semiformal";
60	      for (let v = 1; v <= 30; v++) {
61	        const name = `v${String(v).padStart(4, "0")}.md`;
62	        await fs.writeFile(`${dir}/${name}`, new TextEncoder().encode(`version ${v}`));
63	      }
64	      const names = await fs.readdir(dir);
65	      expect(names).toHaveLength(30);
66	      expect(names).toContain("v0001.md");
67	      expect(names).toContain("v0030.md");
68	      // Read each back and confirm content integrity.
69	      for (let v = 1; v <= 30; v++) {
70	        const name = `v${String(v).padStart(4, "0")}.md`;
71	        const bytes = await fs.readFile(`${dir}/${name}`);
72	        expect(new TextDecoder().decode(bytes!)).toBe(`version ${v}`);
73	      }
74	    });
75	
76	    it("overwrites an existing file in place", async () => {
77	      await fs.writeFile("a.txt", new TextEncoder().encode("first"));
78	      await fs.writeFile("a.txt", new TextEncoder().encode("second"));
79	      expect(new TextDecoder().decode((await fs.readFile("a.txt"))!)).toBe("second");
80	    });
81	  });
82	}
