109	+/**
110	+ * Map-backed in-memory `CorpusFS` for tests (DD-009 sub-task S1).
111	+ *
112	+ * Lets corpus logic be verified in CI even though jsdom has no OPFS. The OPFS
113	+ * adapter and this fake are both asserted against the same shared contract suite
114	+ * (corpusFsContract.ts), so substitutability (LSP) is verified, not assumed.
115	+ *
116	+ * Directories are implicit: a file at "a/b/c.txt" makes "a" and "a/b" listable.
117	+ */
118	+
119	+import type { CorpusFS, CorpusStat } from "../types";
120	+
121	+function normalize(path: string): string {
122	+  return path.replace(/^\/+|\/+$/g, "");
123	+}
124	+
125	+export function createInMemoryCorpusFs(): CorpusFS {
126	+  const files = new Map<string, Uint8Array>();
127	+
128	+  return {
129	+    async readFile(path) {
130	+      return files.get(normalize(path)) ?? null;
131	+    },
132	+
133	+    async writeFile(path, bytes) {
134	+      // Copy so later mutation of the caller's array can't alter stored bytes.
135	+      files.set(normalize(path), bytes.slice());
136	+    },
137	+
138	+    async readdir(path) {
139	+      const dir = normalize(path);
140	+      const prefix = dir === "" ? "" : `${dir}/`;
141	+      const children = new Set<string>();
142	+      for (const key of files.keys()) {
143	+        if (prefix !== "" && !key.startsWith(prefix)) continue;
144	+        const rest = key.slice(prefix.length);
145	+        if (rest === "") continue;
146	+        const next = rest.split("/")[0];
147	+        if (next) children.add(next);
148	+      }
149	+      return [...children].sort();
150	+    },
151	+
152	+    async rm(path) {
153	+      files.delete(normalize(path)); // idempotent: Map.delete on a missing key is a no-op
154	+    },
155	+
156	+    async stat(path): Promise<CorpusStat | null> {
157	+      const bytes = files.get(normalize(path));
158	+      return bytes ? { size: bytes.byteLength } : null;
159	+    },
160	+  };
161	+}
