1	/**
2	 * `workspace.json` manifest schema + codec (DD-009 sub-task S0).
3	 *
4	 * The manifest is the index for one workspace folder: it lists the sources, the
5	 * current-version pointer per artifact type, and the custom-type ids present.
6	 * The per-version artifact bytes live in files (artifacts/<type>/v####.md), not
7	 * here — the manifest only points at the current version so a consumer can open
8	 * a workspace without scanning every file.
9	 *
10	 * Codec contract (arch-review / test-strategy G11): parsing is FAIL-LOUD. A
11	 * malformed or absent manifest must surface as a typed `CorpusError` of kind
12	 * "io" or "browser-storage-cleared", never a silent default-empty manifest that
13	 * would masquerade as "this workspace has no work in it" and mask data loss.
14	 */
15	
16	import { CorpusError } from "./types";
17	
18	export const MANIFEST_VERSION = 1;
19	
20	/** Pointer to the current version of one artifact type. `currentVersion` is the
21	 *  1-based version number whose file is artifacts/<type>/v####.md. */
22	export interface ArtifactPointer {
23	  type: string;
24	  currentVersion: number;
25	}
26	
27	export interface SourceRef {
28	  id: string;
29	  label: string;
30	  /** File extension (no dot) of the stored source bytes under sources/. */
31	  ext: string;
32	}
33	
34	export interface WorkspaceManifest {
35	  manifestVersion: number;
36	  title: string;
37	  createdAt: string;
38	  updatedAt: string;
39	  sources: SourceRef[];
40	  artifacts: ArtifactPointer[];
41	  customTypeIds: string[];
42	}
43	
44	export function createManifest(title: string, now = new Date().toISOString()): WorkspaceManifest {
45	  return {
46	    manifestVersion: MANIFEST_VERSION,
47	    title,
48	    createdAt: now,
49	    updatedAt: now,
50	    sources: [],
51	    artifacts: [],
52	    customTypeIds: [],
53	  };
54	}
55	
56	export function serializeManifest(m: WorkspaceManifest): Uint8Array {
57	  return new TextEncoder().encode(JSON.stringify(m, null, 2));
58	}
59	
60	function isObject(v: unknown): v is Record<string, unknown> {
61	  return typeof v === "object" && v !== null && !Array.isArray(v);
62	}
63	
64	function fail(reason: string): never {
65	  // Manifest parse failure is an i/o-class corruption of the workspace index.
66	  throw new CorpusError({ kind: "io", path: "workspace.json", reason }, `invalid workspace.json: ${reason}`);
67	}
68	
69	/**
70	 * Parse + validate manifest bytes. Throws a `CorpusError` on any malformation —
71	 * a `null` input (file absent) is the caller's responsibility to detect via
72	 * `CorpusFS.readFile` returning `null`; passing `null` here is itself an error.
73	 */
74	export function parseManifest(bytes: Uint8Array | null): WorkspaceManifest {
75	  if (bytes === null) fail("manifest file is absent");
76	  let raw: unknown;
77	  try {
78	    raw = JSON.parse(new TextDecoder().decode(bytes));
79	  } catch (e) {
80	    fail(`not valid JSON (${(e as Error).message})`);
81	  }
82	  if (!isObject(raw)) fail("top-level value is not an object");
83	  if (typeof raw.title !== "string") fail("missing required field: title");
84	  if (typeof raw.manifestVersion !== "number") fail("missing required field: manifestVersion");
85	
86	  const sources: SourceRef[] = Array.isArray(raw.sources)
87	    ? raw.sources.filter(isObject).map((s) => {
88	        if (typeof s.id !== "string" || typeof s.ext !== "string") fail("source entry missing id/ext");
89	        return { id: s.id, label: typeof s.label === "string" ? s.label : s.id, ext: s.ext };
90	      })
91	    : fail("missing or invalid field: sources");
92	
93	  const artifacts: ArtifactPointer[] = Array.isArray(raw.artifacts)
94	    ? raw.artifacts.filter(isObject).map((a) => {
95	        if (typeof a.type !== "string" || typeof a.currentVersion !== "number") {
96	          fail("artifact pointer missing type/currentVersion");
97	        }
98	        return { type: a.type as string, currentVersion: a.currentVersion as number };
99	      })
100	    : fail("missing or invalid field: artifacts");
101	
102	  const customTypeIds: string[] = Array.isArray(raw.customTypeIds)
103	    ? raw.customTypeIds.filter((x): x is string => typeof x === "string")
104	    : fail("missing or invalid field: customTypeIds");
105	
106	  return {
107	    manifestVersion: raw.manifestVersion,
108	    title: raw.title,
109	    createdAt: typeof raw.createdAt === "string" ? raw.createdAt : new Date().toISOString(),
110	    updatedAt: typeof raw.updatedAt === "string" ? raw.updatedAt : new Date().toISOString(),
111	    sources,
112	    artifacts,
113	    customTypeIds,
114	  };
115	}
