7	 *
8	 * Two contracts this file is responsible for (test-strategy G7/G8, arch-review):
9	 *  - SSR / unavailable guard: any call in an environment without
10	 *    `navigator.storage.getDirectory` rejects with a typed `CorpusError`
11	 *    ({kind:"unavailable"}), never a raw `TypeError`.
12	 *  - Failure reification: a quota failure rejects with {kind:"quota-exceeded",
13	 *    substrate:"opfs"} — it is NOT swallowed with console.warn the way the
14	 *    legacy localStorage adapter does (workspaceStore.ts:44-46).
15	 *
16	 * OPFS handle types are declared locally rather than relying on lib.dom, whose
17	 * OPFS surface (notably async `keys()`) varies by TypeScript version — keeping
18	 * our own minimal shapes makes the build stable across upgrades.
19	 */
20	
21	import type { CorpusFS, CorpusStat } from "./types";
22	import { CorpusError } from "./types";
23	
24	// --- Minimal local OPFS typings ---
25	interface OpfsWritable {
26	  // We only ever write Uint8Array; typing it narrowly avoids the lib.dom
27	  // BufferSource/ArrayBufferLike strictness mismatch across TS versions.
28	  write(data: Uint8Array): Promise<void>;
29	  close(): Promise<void>;
30	}
31	interface OpfsFileHandle {
32	  getFile(): Promise<{ size: number; arrayBuffer(): Promise<ArrayBuffer> }>;
33	  createWritable(): Promise<OpfsWritable>;
34	}
35	interface OpfsDirHandle {
36	  getFileHandle(name: string, opts?: { create?: boolean }): Promise<OpfsFileHandle>;
37	  getDirectoryHandle(name: string, opts?: { create?: boolean }): Promise<OpfsDirHandle>;
38	  removeEntry(name: string, opts?: { recursive?: boolean }): Promise<void>;
39	  keys(): AsyncIterableIterator<string>;
40	}
41	
42	function isNotFound(e: unknown): boolean {
43	  return e instanceof DOMException && (e.name === "NotFoundError" || e.name === "TypeMismatchError");
44	}
45	function isQuota(e: unknown): boolean {
46	  return e instanceof DOMException && (e.name === "QuotaExceededError" || e.name === "QUOTA_EXCEEDED_ERR");
47	}
48	
49	async function getRoot(): Promise<OpfsDirHandle> {
50	  const storage = typeof navigator !== "undefined" ? navigator.storage : undefined;
51	  if (!storage || typeof storage.getDirectory !== "function") {
52	    throw new CorpusError({ kind: "unavailable", reason: "navigator.storage.getDirectory is not available (SSR or unsupported browser)" });
53	  }
54	  return (await storage.getDirectory()) as unknown as OpfsDirHandle;
55	}
56	
57	function splitPath(path: string): { dirs: string[]; name: string } {
58	  const parts = path.replace(/^\/+|\/+$/g, "").split("/").filter(Boolean);
59	  const name = parts.pop();
60	  if (!name) throw new CorpusError({ kind: "io", path, reason: "path has no file component" });
61	  return { dirs: parts, name };
62	}
63	
64	/** Walk (optionally creating) directory handles for the given segments. Returns
65	 *  null when `create` is false and a segment is missing. */
66	async function walkDir(root: OpfsDirHandle, dirs: string[], create: boolean): Promise<OpfsDirHandle | null> {
67	  let cur = root;
68	  for (const d of dirs) {
69	    try {
70	      cur = await cur.getDirectoryHandle(d, { create });
71	    } catch (e) {
72	      if (!create && isNotFound(e)) return null;
73	      throw e;
74	    }
75	  }
76	  return cur;
77	}
78	
79	function wrap(path: string, e: unknown): never {
80	  if (e instanceof CorpusError) throw e;
81	  if (isQuota(e)) throw new CorpusError({ kind: "quota-exceeded", substrate: "opfs" });
82	  throw new CorpusError({ kind: "io", path, reason: (e as Error)?.message ?? String(e) });
83	}
84	
85	export function createOpfsCorpusFs(): CorpusFS {
86	  return {
87	    async readFile(path) {
88	      try {
89	        const root = await getRoot();
90	        const { dirs, name } = splitPath(path);
91	        const dir = await walkDir(root, dirs, false);
92	        if (!dir) return null;
93	        let fh: OpfsFileHandle;
94	        try {
95	          fh = await dir.getFileHandle(name, { create: false });
96	        } catch (e) {
97	          if (isNotFound(e)) return null;
98	          throw e;
99	        }
100	        const file = await fh.getFile();
101	        return new Uint8Array(await file.arrayBuffer());
102	      } catch (e) {
103	        wrap(path, e);
104	      }
105	    },
106	
107	    async writeFile(path, bytes) {
108	      try {
109	        const root = await getRoot();
110	        const { dirs, name } = splitPath(path);
111	        const dir = await walkDir(root, dirs, true);
112	        const fh = await dir!.getFileHandle(name, { create: true });
113	        const w = await fh.createWritable();
114	        try {
115	          // Pass a fresh ArrayBuffer view; some implementations dislike shared buffers.
116	          await w.write(bytes);
117	        } finally {
118	          await w.close();
119	        }
120	      } catch (e) {
121	        wrap(path, e);
122	      }
123	    },
124	
125	    async readdir(path) {
126	      try {
127	        const root = await getRoot();
128	        const dirs = path.replace(/^\/+|\/+$/g, "").split("/").filter(Boolean);
129	        const dir = await walkDir(root, dirs, false);
130	        if (!dir) return [];
131	        const names: string[] = [];
132	        for await (const key of dir.keys()) names.push(key);
133	        return names.sort();
134	      } catch (e) {
135	        wrap(path, e);
136	      }
137	    },
138	
139	    async rm(path) {
140	      try {
141	        const root = await getRoot();
142	        const { dirs, name } = splitPath(path);
143	        const dir = await walkDir(root, dirs, false);
144	        if (!dir) return; // idempotent: parent dir missing -> nothing to remove
145	        try {
146	          await dir.removeEntry(name);
147	        } catch (e) {
148	          if (isNotFound(e)) return; // idempotent: file already gone
149	          throw e;
150	        }
151	      } catch (e) {
152	        wrap(path, e);
153	      }
154	    },
155	
156	    async stat(path): Promise<CorpusStat | null> {
157	      try {
158	        const root = await getRoot();
159	        const { dirs, name } = splitPath(path);
160	        const dir = await walkDir(root, dirs, false);
161	        if (!dir) return null;
162	        let fh: OpfsFileHandle;
163	        try {
164	          fh = await dir.getFileHandle(name, { create: false });
165	        } catch (e) {
166	          if (isNotFound(e)) return null;
167	          throw e;
168	        }
169	        const file = await fh.getFile();
170	        return { size: file.size };
171	      } catch (e) {
172	        wrap(path, e);
173	      }
174	    },
175	  };
176	}
