98	// ---------------------------------------------------------------------------
99	// The filesystem interface.
100	// ---------------------------------------------------------------------------
101	
102	export interface CorpusStat {
103	  size: number;
104	}
105	
106	/**
107	 * Async, bytes-and-paths filesystem seam. Paths are POSIX-style, relative to the
108	 * corpus root, using "/" separators and no leading slash (e.g.
109	 * "workspaces/my-slug/artifacts/semiformal/v0001.md"). Implementations create
110	 * intermediate directories on write.
111	 */
112	export interface CorpusFS {
113	  /** Returns file bytes, or `null` if the path does not exist. Rejects with a
114	   *  `CorpusError` for any other failure. */
115	  readFile(path: string): Promise<Uint8Array | null>;
116	  /** Writes bytes, creating intermediate directories as needed. */
117	  writeFile(path: string, bytes: Uint8Array): Promise<void>;
118	  /** Lists immediate child names of a directory; `[]` if the directory is
119	   *  missing or empty. Names only, not full paths. */
120	  readdir(path: string): Promise<string[]>;
121	  /** Removes a file. Idempotent: resolves (no-op) if the path does not exist. */
122	  rm(path: string): Promise<void>;
123	  /** Returns `{ size }` for an existing file, or `null` if it does not exist. */
124	  stat(path: string): Promise<CorpusStat | null>;
125	}
