31	
32	function isObject(v: unknown): v is Record<string, unknown> {
33	  return typeof v === "object" && v !== null && !Array.isArray(v);
34	}
35	
36	const VALID_ARTIFACT_SOURCES = new Set(["generated", "ai-edit", "manual-edit"]);
37	
38	/** Validate an individual ArtifactVersion from deserialized JSON. */
39	function coerceArtifactVersion(raw: unknown): ArtifactVersion | null {
40	  if (!isObject(raw)) return null;
41	  if (typeof raw.content !== "string") return null;
42	  if (typeof raw.id !== "string") return null;
43	  return {
44	    id: raw.id,
45	    content: raw.content,
46	    createdAt: typeof raw.createdAt === "string" ? raw.createdAt : new Date().toISOString(),
47	    source: VALID_ARTIFACT_SOURCES.has(raw.source as string) ? raw.source as ArtifactVersion["source"] : "generated",
48	    editInstruction: typeof raw.editInstruction === "string" ? raw.editInstruction : undefined,
49	  };
50	}
51	
52	/** Validate and coerce an ArtifactRecord from deserialized JSON. */
53	function coerceArtifactRecord(raw: unknown, key: ArtifactKey): ArtifactRecord | undefined {
54	  if (!isObject(raw)) return undefined;
55	  const versions = Array.isArray(raw.versions)
56	    ? (raw.versions as unknown[]).map(coerceArtifactVersion).filter((v): v is ArtifactVersion => v !== null)
57	    : [];
58	  if (versions.length === 0) return undefined;
59	  const idx = typeof raw.currentVersionIndex === "number" ? raw.currentVersionIndex : versions.length - 1;
60	  return {
61	    type: key,
62	    versions,
63	    currentVersionIndex: Math.max(0, Math.min(idx, versions.length - 1)),
64	  };
65	}
