67	/** Coerce deserialized persisted state to safe types before merging into the store. */
68	function coercePersistedState(persisted: Record<string, unknown>): Partial<WorkspaceState> {
69	  const result: Partial<WorkspaceState> = {};
70	
71	  if (typeof persisted.sourceText === "string") result.sourceText = persisted.sourceText;
72	  if (Array.isArray(persisted.extractedFiles)) {
73	    result.extractedFiles = (persisted.extractedFiles as unknown[]).filter(isObject).map((f) => ({
74	      name: typeof f.name === "string" ? f.name : "",
75	      text: typeof f.text === "string" ? f.text : "",
76	    }));
77	  }
78	  if (typeof persisted.contextText === "string") result.contextText = persisted.contextText;
79	  if (typeof persisted.semiformalText === "string") result.semiformalText = persisted.semiformalText;
80	  if (typeof persisted.leanCode === "string") result.leanCode = persisted.leanCode;
81	  if (typeof persisted.semiformalDirty === "boolean") result.semiformalDirty = persisted.semiformalDirty;
82	  if (typeof persisted.verificationStatus === "string") {
83	    result.verificationStatus = sanitizeVerificationStatus(persisted.verificationStatus);
84	  }
85	  if (typeof persisted.verificationErrors === "string") result.verificationErrors = persisted.verificationErrors;
86	
87	  // Validate artifact records
88	  if (isObject(persisted.artifacts)) {
89	    const artifacts: Partial<Record<ArtifactKey, ArtifactRecord>> = {};
90	    const validKeys: ArtifactKey[] = ["causal-graph", "statistical-model", "property-tests", "dialectical-map", "counterexamples"];
91	    for (const key of validKeys) {
92	      const rec = coerceArtifactRecord((persisted.artifacts as Record<string, unknown>)[key], key);
93	      if (rec) artifacts[key] = rec;
94	    }
95	    result.artifacts = artifacts;
96	  }
97	
98	  // Decomposition — reuse the thorough field-by-field coercion from workspacePersistence
99	  if (isObject(persisted.decomposition)) {
100	    result.decomposition = coerceDecomposition(persisted.decomposition);
101	  }
102	
103	  // Custom artifact types — accept only entries whose id begins with "custom-"
104	  if (Array.isArray(persisted.customArtifactTypes)) {
105	    result.customArtifactTypes = (persisted.customArtifactTypes as unknown[])
106	      .filter(isObject)
107	      .filter((c) => typeof c.id === "string" && (c.id as string).startsWith("custom-"))
108	      .map((c) => c as unknown as CustomArtifactTypeDefinition);
109	  }
110	  if (isObject(persisted.customArtifactData)) {
111	    const data: Record<string, string | null> = {};
112	    for (const [k, v] of Object.entries(persisted.customArtifactData)) {
113	      if (k.startsWith("custom-") && (typeof v === "string" || v === null)) data[k] = v;
114	    }
115	    result.customArtifactData = data;
116	  }
117	
118	  return result;
119	}
