419	+/**
420	+ * `workspace.json` manifest schema + codec (DD-009 sub-task S0).
421	+ *
422	+ * The manifest is the index for one workspace folder: it lists the sources, the
423	+ * current-version pointer per artifact type, and the custom-type ids present.
424	+ * The per-version artifact bytes live in files (artifacts/<type>/v####.md), not
425	+ * here — the manifest only points at the current version so a consumer can open
426	+ * a workspace without scanning every file.
427	+ *
428	+ * Codec contract (arch-review / test-strategy G11): parsing is FAIL-LOUD. A
429	+ * malformed or absent manifest must surface as a typed `CorpusError` of kind
430	+ * "io" or "browser-storage-cleared", never a silent default-empty manifest that
431	+ * would masquerade as "this workspace has no work in it" and mask data loss.
432	+ */
433	+
434	+import { CorpusError } from "./types";
435	+
436	+export const MANIFEST_VERSION = 1;
437	+
438	+/** Pointer to the current version of one artifact type. `currentVersion` is the
439	+ *  1-based version number whose file is artifacts/<type>/v####.md. */
440	+export interface ArtifactPointer {
441	+  type: string;
442	+  currentVersion: number;
443	+}
444	+
445	+export interface SourceRef {
446	+  id: string;
447	+  label: string;
448	+  /** File extension (no dot) of the stored source bytes under sources/. */
449	+  ext: string;
450	+}
