452	+export interface WorkspaceManifest {
453	+  manifestVersion: number;
454	+  title: string;
455	+  createdAt: string;
456	+  updatedAt: string;
457	+  sources: SourceRef[];
458	+  artifacts: ArtifactPointer[];
459	+  customTypeIds: string[];
460	+}
461	+
462	+export function createManifest(title: string, now = new Date().toISOString()): WorkspaceManifest {
463	+  return {
464	+    manifestVersion: MANIFEST_VERSION,
465	+    title,
466	+    createdAt: now,
467	+    updatedAt: now,
468	+    sources: [],
469	+    artifacts: [],
470	+    customTypeIds: [],
471	+  };
472	+}
473	+
474	+export function serializeManifest(m: WorkspaceManifest): Uint8Array {
475	+  return new TextEncoder().encode(JSON.stringify(m, null, 2));
476	+}
