482	+function fail(reason: string): never {
483	+  // Manifest parse failure is an i/o-class corruption of the workspace index.
484	+  throw new CorpusError({ kind: "io", path: "workspace.json", reason }, `invalid workspace.json: ${reason}`);
485	+}
486	+
487	+/**
488	+ * Parse + validate manifest bytes. Throws a `CorpusError` on any malformation —
489	+ * a `null` input (file absent) is the caller's responsibility to detect via
490	+ * `CorpusFS.readFile` returning `null`; passing `null` here is itself an error.
491	+ */
492	+export function parseManifest(bytes: Uint8Array | null): WorkspaceManifest {
493	+  if (bytes === null) fail("manifest file is absent");
494	+  let raw: unknown;
495	+  try {
496	+    raw = JSON.parse(new TextDecoder().decode(bytes));
497	+  } catch (e) {
498	+    fail(`not valid JSON (${(e as Error).message})`);
499	+  }
500	+  if (!isObject(raw)) fail("top-level value is not an object");
501	+  if (typeof raw.title !== "string") fail("missing required field: title");
502	+  if (typeof raw.manifestVersion !== "number") fail("missing required field: manifestVersion");
503	+
504	+  const sources: SourceRef[] = Array.isArray(raw.sources)
505	+    ? raw.sources.filter(isObject).map((s) => {
506	+        if (typeof s.id !== "string" || typeof s.ext !== "string") fail("source entry missing id/ext");
507	+        return { id: s.id, label: typeof s.label === "string" ? s.label : s.id, ext: s.ext };
508	+      })
509	+    : fail("missing or invalid field: sources");
510	+
511	+  const artifacts: ArtifactPointer[] = Array.isArray(raw.artifacts)
512	+    ? raw.artifacts.filter(isObject).map((a) => {
513	+        if (typeof a.type !== "string" || typeof a.currentVersion !== "number") {
514	+          fail("artifact pointer missing type/currentVersion");
515	+        }
516	+        return { type: a.type as string, currentVersion: a.currentVersion as number };
517	+      })
518	+    : fail("missing or invalid field: artifacts");
519	+
520	+  const customTypeIds: string[] = Array.isArray(raw.customTypeIds)
521	+    ? raw.customTypeIds.filter((x): x is string => typeof x === "string")
522	+    : fail("missing or invalid field: customTypeIds");
523	+
524	+  return {
525	+    manifestVersion: raw.manifestVersion,
526	+    title: raw.title,
527	+    createdAt: typeof raw.createdAt === "string" ? raw.createdAt : new Date().toISOString(),
528	+    updatedAt: typeof raw.updatedAt === "string" ? raw.updatedAt : new Date().toISOString(),
529	+    sources,
530	+    artifacts,
531	+    customTypeIds,
532	+  };
533	+}
