537	--- /dev/null
538	+++ b/app/lib/corpus/opfsAdapter.ts
539	@@ -0,0 +1,176 @@
540	+/**
541	+ * OPFS-backed `CorpusFS` adapter (DD-009 sub-task S1).
542	+ *
543	+ * Implements the corpus filesystem over the Origin Private File System
544	+ * (`navigator.storage.getDirectory()`). This is the always-on local working
545	+ * copy; FSA mirror (S2) and git (S3) layer on top.
546	+ *
547	+ * Two contracts this file is responsible for (test-strategy G7/G8, arch-review):
548	+ *  - SSR / unavailable guard: any call in an environment without
549	+ *    `navigator.storage.getDirectory` rejects with a typed `CorpusError`
550	+ *    ({kind:"unavailable"}), never a raw `TypeError`.
551	+ *  - Failure reification: a quota failure rejects with {kind:"quota-exceeded",
552	+ *    substrate:"opfs"} — it is NOT swallowed with console.warn the way the
553	+ *    legacy localStorage adapter does (workspaceStore.ts:44-46).
554	+ *
555	+ * OPFS handle types are declared locally rather than relying on lib.dom, whose
556	+ * OPFS surface (notably async `keys()`) varies by TypeScript version — keeping
557	+ * our own minimal shapes makes the build stable across upgrades.
558	+ */
559	+
560	+import type { CorpusFS, CorpusStat } from "./types";
561	+import { CorpusError } from "./types";
562	+
563	+// --- Minimal local OPFS typings ---
564	+interface OpfsWritable {
565	+  // We only ever write Uint8Array; typing it narrowly avoids the lib.dom
566	+  // BufferSource/ArrayBufferLike strictness mismatch across TS versions.
567	+  write(data: Uint8Array): Promise<void>;
568	+  close(): Promise<void>;
569	+}
570	+interface OpfsFileHandle {
571	+  getFile(): Promise<{ size: number; arrayBuffer(): Promise<ArrayBuffer> }>;
572	+  createWritable(): Promise<OpfsWritable>;
573	+}
574	+interface OpfsDirHandle {
575	+  getFileHandle(name: string, opts?: { create?: boolean }): Promise<OpfsFileHandle>;
576	+  getDirectoryHandle(name: string, opts?: { create?: boolean }): Promise<OpfsDirHandle>;
577	+  removeEntry(name: string, opts?: { recursive?: boolean }): Promise<void>;
578	+  keys(): AsyncIterableIterator<string>;
579	+}
580	+
581	+function isNotFound(e: unknown): boolean {
582	+  return e instanceof DOMException && (e.name === "NotFoundError" || e.name === "TypeMismatchError");
583	+}
584	+function isQuota(e: unknown): boolean {
585	+  return e instanceof DOMException && (e.name === "QuotaExceededError" || e.name === "QUOTA_EXCEEDED_ERR");
586	+}
587	+
588	+async function getRoot(): Promise<OpfsDirHandle> {
589	+  const storage = typeof navigator !== "undefined" ? navigator.storage : undefined;
590	+  if (!storage || typeof storage.getDirectory !== "function") {
591	+    throw new CorpusError({ kind: "unavailable", reason: "navigator.storage.getDirectory is not available (SSR or unsupported browser)" });
592	+  }
593	+  return (await storage.getDirectory()) as unknown as OpfsDirHandle;
594	+}
595	+
596	+function splitPath(path: string): { dirs: string[]; name: string } {
597	+  const parts = path.replace(/^\/+|\/+$/g, "").split("/").filter(Boolean);
598	+  const name = parts.pop();
599	+  if (!name) throw new CorpusError({ kind: "io", path, reason: "path has no file component" });
600	+  return { dirs: parts, name };
601	+}
602	+
603	+/** Walk (optionally creating) directory handles for the given segments. Returns
604	+ *  null when `create` is false and a segment is missing. */
605	+async function walkDir(root: OpfsDirHandle, dirs: string[], create: boolean): Promise<OpfsDirHandle | null> {
606	+  let cur = root;
607	+  for (const d of dirs) {
608	+    try {
609	+      cur = await cur.getDirectoryHandle(d, { create });
610	+    } catch (e) {
611	+      if (!create && isNotFound(e)) return null;
612	+      throw e;
613	+    }
614	+  }
615	+  return cur;
616	+}
617	+
618	+function wrap(path: string, e: unknown): never {
619	+  if (e instanceof CorpusError) throw e;
620	+  if (isQuota(e)) throw new CorpusError({ kind: "quota-exceeded", substrate: "opfs" });
621	+  throw new CorpusError({ kind: "io", path, reason: (e as Error)?.message ?? String(e) });
622	+}
623	+
624	+export function createOpfsCorpusFs(): CorpusFS {
625	+  return {
626	+    async readFile(path) {
627	+      try {
628	+        const root = await getRoot();
629	+        const { dirs, name } = splitPath(path);
630	+        const dir = await walkDir(root, dirs, false);
631	+        if (!dir) return null;
632	+        let fh: OpfsFileHandle;
633	+        try {
634	+          fh = await dir.getFileHandle(name, { create: false });
635	+        } catch (e) {
636	+          if (isNotFound(e)) return null;
637	+          throw e;
638	+        }
639	+        const file = await fh.getFile();
640	+        return new Uint8Array(await file.arrayBuffer());
641	+      } catch (e) {
642	+        wrap(path, e);
643	+      }
644	+    },
645	+
646	+    async writeFile(path, bytes) {
647	+      try {
648	+        const root = await getRoot();
649	+        const { dirs, name } = splitPath(path);
650	+        const dir = await walkDir(root, dirs, true);
651	+        const fh = await dir!.getFileHandle(name, { create: true });
652	+        const w = await fh.createWritable();
653	+        try {
654	+          // Pass a fresh ArrayBuffer view; some implementations dislike shared buffers.
655	+          await w.write(bytes);
656	+        } finally {
657	+          await w.close();
658	+        }
659	+      } catch (e) {
660	+        wrap(path, e);
661	+      }
662	+    },
663	+
664	+    async readdir(path) {
665	+      try {
666	+        const root = await getRoot();
667	+        const dirs = path.replace(/^\/+|\/+$/g, "").split("/").filter(Boolean);
668	+        const dir = await walkDir(root, dirs, false);
669	+        if (!dir) return [];
670	+        const names: string[] = [];
671	+        for await (const key of dir.keys()) names.push(key);
672	+        return names.sort();
673	+      } catch (e) {
674	+        wrap(path, e);
675	+      }
676	+    },
677	+
678	+    async rm(path) {
679	+      try {
680	+        const root = await getRoot();
681	+        const { dirs, name } = splitPath(path);
682	+        const dir = await walkDir(root, dirs, false);
683	+        if (!dir) return; // idempotent: parent dir missing -> nothing to remove
684	+        try {
685	+          await dir.removeEntry(name);
686	+        } catch (e) {
687	+          if (isNotFound(e)) return; // idempotent: file already gone
688	+          throw e;
689	+        }
690	+      } catch (e) {
691	+        wrap(path, e);
692	+      }
693	+    },
694	+
695	+    async stat(path): Promise<CorpusStat | null> {
696	+      try {
697	+        const root = await getRoot();
698	+        const { dirs, name } = splitPath(path);
699	+        const dir = await walkDir(root, dirs, false);
700	+        if (!dir) return null;
701	+        let fh: OpfsFileHandle;
702	+        try {
703	+          fh = await dir.getFileHandle(name, { create: false });
704	+        } catch (e) {
705	+          if (isNotFound(e)) return null;
706	+          throw e;
707	+        }
708	+        const file = await fh.getFile();
709	+        return { size: file.size };
710	+      } catch (e) {
711	+        wrap(path, e);
712	+      }
713	+    },
714	+  };
715	+}
