721	@@ -0,0 +1,110 @@
722	+/**
723	+ * Corpus folder-layout path builders (DD-009 sub-task S0).
724	+ *
725	+ * The on-disk shape (DD-009 §Folder layout):
726	+ *
727	+ *   <corpus-root>/
728	+ *   ├── settings.json
729	+ *   └── workspaces/<slug>/
730	+ *       ├── workspace.json
731	+ *       ├── sources/<source-id>.<ext>
732	+ *       ├── artifacts/<type>/v####.md   (+ meta.json per type)
733	+ *       ├── custom-types/<custom-type-id>.json
734	+ *       └── decomposition/...
735	+ *
736	+ * All builders return POSIX-style paths relative to the corpus root (no leading
737	+ * slash), suitable for passing straight to a `CorpusFS`. The only source of
738	+ * corpus paths is this module — callers must never hand-concatenate, so the
739	+ * traversal guard in `workspaceSlug` is the single choke point that keeps
740	+ * untrusted workspace titles inside `workspaces/`.
741	+ */
742	+
743	+/** Width of the zero-padded version number in artifact filenames (v0001.md). */
744	+const VERSION_PAD = 4;
745	+
746	+/** Characters allowed in a sanitized slug or id segment. Everything else is
747	+ *  collapsed to a hyphen so a value can never contain "/", "\\", "." runs, or
748	+ *  control characters that would let it escape its directory. */
749	+const SAFE_SEGMENT = /[^a-zA-Z0-9_-]+/g;
750	+
751	+/**
752	+ * Sanitize a workspace title into a filesystem-safe slug that cannot escape
753	+ * `workspaces/`. Strips path separators, dot-segments, and unicode; collapses
754	+ * runs of unsafe characters to a single hyphen; trims leading/trailing hyphens.
755	+ * Throws if nothing safe remains (an all-unsafe title must not silently become "").
756	+ */
757	+export function workspaceSlug(title: string): string {
758	+  const slug = title
759	+    .normalize("NFKD")
760	+    .replace(SAFE_SEGMENT, "-")
761	+    .replace(/-{2,}/g, "-")
762	+    .replace(/^-+|-+$/g, "")
763	+    .toLowerCase();
764	+  if (!slug) {
765	+    throw new Error(`workspace title produced an empty slug: ${JSON.stringify(title)}`);
766	+  }
767	+  return slug;
768	+}
769	+
770	+/** Sanitize an arbitrary id (source id, custom-type id, artifact type) for use
771	+ *  as a single path segment. Same guarantees as `workspaceSlug` but preserves
772	+ *  case (ids are typically already safe, e.g. "custom-abc123"). */
773	+export function safeSegment(id: string): string {
774	+  const seg = id.normalize("NFKD").replace(SAFE_SEGMENT, "-").replace(/-{2,}/g, "-").replace(/^-+|-+$/g, "");
775	+  if (!seg) {
776	+    throw new Error(`id produced an empty path segment: ${JSON.stringify(id)}`);
777	+  }
778	+  return seg;
779	+}
780	+
781	+/** Sanitize a file extension to alphanumerics; defaults to "bin" if empty. */
782	+function safeExt(ext: string): string {
783	+  const e = ext.replace(/^\.+/, "").replace(/[^a-zA-Z0-9]+/g, "").toLowerCase();
784	+  return e || "bin";
785	+}
786	+
787	+// --- Path builders (all relative to corpus root) ---------------------------
788	+
789	+export const SETTINGS_PATH = "settings.json";
790	+
791	+export function workspaceDir(slug: string): string {
792	+  return `workspaces/${workspaceSlug(slug)}`;
793	+}
794	+
795	+export function workspaceManifestPath(slug: string): string {
796	+  return `${workspaceDir(slug)}/workspace.json`;
797	+}
798	+
799	+export function sourcePath(slug: string, sourceId: string, ext: string): string {
800	+  return `${workspaceDir(slug)}/sources/${safeSegment(sourceId)}.${safeExt(ext)}`;
801	+}
802	+
803	+export function artifactDir(slug: string, artifactType: string): string {
804	+  return `${workspaceDir(slug)}/artifacts/${safeSegment(artifactType)}`;
805	+}
806	+
807	+/** Zero-padded version file, e.g. artifactVersionPath(s,"semiformal",1) ->
808	+ *  "workspaces/<s>/artifacts/semiformal/v0001.md". `version` is 1-based. */
809	+export function artifactVersionPath(slug: string, artifactType: string, version: number): string {
810	+  if (!Number.isInteger(version) || version < 1) {
811	+    throw new Error(`artifact version must be a positive integer, got ${version}`);
812	+  }
813	+  const v = String(version).padStart(VERSION_PAD, "0");
814	+  return `${artifactDir(slug, artifactType)}/v${v}.md`;
815	+}
816	+
817	+export function artifactMetaPath(slug: string, artifactType: string): string {
818	+  return `${artifactDir(slug, artifactType)}/meta.json`;
819	+}
820	+
821	+export function customTypePath(slug: string, customTypeId: string): string {
822	+  return `${workspaceDir(slug)}/custom-types/${safeSegment(customTypeId)}.json`;
823	+}
824	+
825	+export function decompositionDir(slug: string): string {
826	+  return `${workspaceDir(slug)}/decomposition`;
827	+}
828	+
829	+export function decompositionGraphLayoutPath(slug: string): string {
830	+  return `${decompositionDir(slug)}/graph-layout.json`;
831	+}
