835	--- /dev/null
836	+++ b/app/lib/corpus/storeAdapter.ts
837	@@ -0,0 +1,76 @@
838	+/**
839	+ * Storage-seam selection for the Zustand workspace store (DD-009 sub-task S1).
840	+ *
841	+ * `resolveWorkspaceStorage()` returns the zustand persist storage: the existing
842	+ * debounced localStorage adapter by default, or a CorpusFS-backed storage when
843	+ * the dev flag is on. The injection seam is typed as `CorpusFS` (arch-review
844	+ * finding 3) so the S3 worker-proxy implementation drops in here without the
845	+ * store ever knowing which adapter it talks to.
846	+ *
847	+ * In S1 the persist blob is stored as a SINGLE file via CorpusFS (blob mode) —
848	+ * the files-per-artifact folder layout (layout.ts/manifest.ts) is built but not
849	+ * used by the store until S4. This keeps S1 a pure substrate swap.
850	+ */
851	+
852	+import type { StateStorage } from "zustand/middleware";
853	+import type { CorpusFS } from "./types";
854	+import { createOpfsCorpusFs } from "./opfsAdapter";
855	+import { isCorpusEnabled } from "./flag";
856	+
857	+// ---------------------------------------------------------------------------
858	+// Default: debounced localStorage (moved verbatim from workspaceStore.ts so the
859	+// OFF path is byte-for-byte the prior behavior — see the characterization test).
860	+// Reads are synchronous (instant); writes are debounced by 300ms.
861	+// ---------------------------------------------------------------------------
862	+export function createDebouncedLocalStorage(): StateStorage {
863	+  let pending: ReturnType<typeof setTimeout> | null = null;
864	+  return {
865	+    getItem: (name) => localStorage.getItem(name),
866	+    setItem: (name, value) => {
867	+      if (pending) clearTimeout(pending);
868	+      pending = setTimeout(() => {
869	+        try {
870	+          localStorage.setItem(name, value);
871	+        } catch (e) {
872	+          console.warn("Failed to persist workspace (localStorage quota exceeded):", e);
873	+        }
874	+        pending = null;
875	+      }, 300);
876	+    },
877	+    removeItem: (name) => {
878	+      if (pending) clearTimeout(pending);
879	+      pending = null;
880	+      localStorage.removeItem(name);
881	+    },
882	+  };
883	+}
884	+
885	+// ---------------------------------------------------------------------------
886	+// Corpus-backed storage: stores the persist blob as one file under `state/`.
887	+// The seam type is CorpusFS, not a concrete adapter (arch-review finding 3).
888	+// ---------------------------------------------------------------------------
889	+export function createCorpusBackedStorage(fs: CorpusFS): StateStorage {
890	+  const enc = new TextEncoder();
891	+  const dec = new TextDecoder();
892	+  const pathFor = (name: string) => `state/${name}.json`;
893	+  return {
894	+    getItem: async (name) => {
895	+      const bytes = await fs.readFile(pathFor(name));
896	+      return bytes ? dec.decode(bytes) : null;
897	+    },
898	+    setItem: async (name, value) => {
899	+      await fs.writeFile(pathFor(name), enc.encode(value));
900	+    },
901	+    removeItem: async (name) => {
902	+      await fs.rm(pathFor(name));
903	+    },
904	+  };
905	+}
906	+
907	+/** Selected once when the store's persist middleware initializes. */
908	+export function resolveWorkspaceStorage(): StateStorage {
909	+  if (isCorpusEnabled()) {
910	+    return createCorpusBackedStorage(createOpfsCorpusFs());
911	+  }
912	+  return createDebouncedLocalStorage();
913	+}
