916	index 0000000..358519d
917	--- /dev/null
918	+++ b/app/lib/corpus/types.ts
919	@@ -0,0 +1,125 @@
920	+/**
921	+ * Corpus filesystem abstraction (DD-009 sub-task S0+S1).
922	+ *
923	+ * `CorpusFS` is the single FS seam every later sub-task binds to:
924	+ *   - S1 OPFS adapter implements it (always-on local cache)
925	+ *   - S2 FSA folder mirror writes through it
926	+ *   - S4 migration + session model reads/writes the folder layout through it
927	+ *
928	+ * Design notes (see docs/decisions/009-artifact-corpus-architecture.md and
929	+ * docs/reviews/architecture-review.md):
930	+ *  - Bytes + paths, not strings + keys. Sources are binary (PDFs), so the
931	+ *    interface is `Uint8Array`-oriented; do not narrow it to strings.
932	+ *  - Async everywhere. OPFS and FSA are both async, and DD-009 mandates the
933	+ *    writer eventually run in a worker (S3). An async interface makes that a
934	+ *    transport swap, not an interface change — so consumers MUST bind to this
935	+ *    interface, never to a concrete adapter (arch-review finding 3).
936	+ *  - "Not found" is `null` from `readFile`/`stat` and `[]` from `readdir`;
937	+ *    everything else rejects with a `CorpusError`. Callers never see `undefined`.
938	+ *  - GIT IS NOT PART OF THIS INTERFACE. S3's commit/log/push/pull belong on a
939	+ *    separate `CorpusGit` interface that operates *over* a `CorpusFS`. Do not add
940	+ *    git methods here — that would force the in-memory fake and every non-git
941	+ *    consumer to stub operations they don't use (arch-review finding 2, ISP).
942	+ */
943	+
944	+// ---------------------------------------------------------------------------
945	+// Error model — one source of truth for the kind set (arch-review finding 1).
946	+// `CorpusError` is the thrown form; `CorpusWorkerError` is its postMessage-
947	+// serializable twin. They differ only in transport, never in the kind set.
948	+// ---------------------------------------------------------------------------
949	+
950	+/** Which substrate raised a space/quota failure. Substrate-neutral so S2 (FSA)
951	+ *  and future caches reuse the same `quota-exceeded` kind rather than minting
952	+ *  adapter-specific kinds the exhaustive switches would all have to learn. */
953	+export type CorpusSubstrate = "opfs" | "fsa" | "remote";
954	+
955	+/**
956	+ * The complete set of corpus failure kinds. Every exhaustive `switch` over a
957	+ * corpus error binds to this union; adding a kind here forces every consumer to
958	+ * handle it at compile time (the failure-driven-UI mandate, DD-009 §Failure-driven).
959	+ */
960	+export type CorpusErrorKind =
961	+  | { kind: "not-found"; path: string }
962	+  | { kind: "quota-exceeded"; substrate: CorpusSubstrate; needed?: number; available?: number }
963	+  | { kind: "unavailable"; reason: string } // e.g. SSR / no navigator.storage
964	+  | { kind: "io"; path: string; reason: string }
965	+  | { kind: "fsa-permission-revoked" }
966	+  | { kind: "remote-auth-expired" }
967	+  | { kind: "browser-storage-cleared" }
968	+  | { kind: "git-conflict"; path: string };
969	+
970	+/** Thrown form of a corpus failure. `detail` carries the discriminated kind. */
971	+export class CorpusError extends Error {
972	+  readonly detail: CorpusErrorKind;
973	+  constructor(detail: CorpusErrorKind, message?: string) {
974	+    super(message ?? describeCorpusError(detail));
975	+    this.name = "CorpusError";
976	+    this.detail = detail;
977	+  }
978	+}
979	+
980	+/** Serializable twin for crossing a worker boundary (S3). Reconstruct with
981	+ *  `new CorpusError(payload.detail, payload.message)` on the main thread. */
982	+export type CorpusWorkerError = {
983	+  __corpusError: true;
984	+  detail: CorpusErrorKind;
985	+  message: string;
986	+};
987	+
988	+export function toWorkerError(err: CorpusError): CorpusWorkerError {
989	+  return { __corpusError: true, detail: err.detail, message: err.message };
990	+}
991	+
992	+export function isCorpusWorkerError(v: unknown): v is CorpusWorkerError {
993	+  return typeof v === "object" && v !== null && (v as { __corpusError?: unknown }).__corpusError === true;
994	+}
995	+
