/** THROWAWAY verification test — delete after running. */
import { describe, it, expect, afterEach } from "vitest";
import { createOpfsCorpusFs } from "../opfsAdapter";
import { CorpusError } from "../types";

const original = Object.getOwnPropertyDescriptor(navigator, "storage");
function setStorage(value: unknown): void {
  Object.defineProperty(navigator, "storage", { configurable: true, value });
}
afterEach(() => {
  if (original) Object.defineProperty(navigator, "storage", original);
  else setStorage(undefined);
});

describe("verify: quota rejection from write() masked by close() TypeError", () => {
  it("shows what kind surfaces when write() rejects quota and close() rejects TypeError", async () => {
    const fakeRoot = {
      async getFileHandle() {
        return {
          async createWritable() {
            return {
              async write() {
                // Quota hit mid-write: stream becomes errored.
                throw new DOMException("quota", "QuotaExceededError");
              },
              async close() {
                // Per WHATWG Streams, close() on an errored stream rejects TypeError.
                throw new TypeError("Cannot close an errored writable stream");
              },
            };
          },
        };
      },
      async getDirectoryHandle() {
        return fakeRoot;
      },
      async removeEntry() {},
      async *keys() {},
    };
    setStorage({ getDirectory: async () => fakeRoot });

    const fs = createOpfsCorpusFs();
    let caught: unknown;
    try {
      await fs.writeFile("a.txt", new TextEncoder().encode("hi"));
    } catch (e) {
      caught = e;
    }
    expect(caught).toBeInstanceOf(CorpusError);
    const detail = (caught as CorpusError).detail;
    // Log the actual observed kind for the verdict:
    console.log("OBSERVED KIND:", JSON.stringify(detail));
    // Claim says this will be 'io' (masking). Assert claim:
    expect(detail.kind).toBe("io");
  });

  it("plain JS semantics: rejection in awaited finally replaces original rejection", async () => {
    async function f() {
      try {
        throw new Error("original");
      } finally {
        // eslint-disable-next-line no-unsafe-finally
        await Promise.reject(new TypeError("from finally"));
      }
    }
    let caught: unknown;
    try {
      await f();
    } catch (e) {
      caught = e;
    }
    expect(caught).toBeInstanceOf(TypeError);
    expect((caught as Error).message).toBe("from finally");
  });
});

